INSERT INTO public.edhas_evaluaciones VALUES (1, 'c40a6f5d-05e4-4195-bddb-c879e69c7e4c', 'EDHAS-20260813-001', '2026-08-13', 'Leidy Montes', '29398080', '3122081011', 'Cra 2 # 15B-84', 'Fray Peña', 'Casa unifamiliar', 'Media', 'Afectaciones estructurales o funcionales parciales', 'Caída de cubierta, caja antigua, daño en paredes, losa suelta, se recomienda evitar la zona de la entrada hasta intervención.', 'Demoler losa, intervenir la cubierta que está en madera y teja de barro, reforzar paredes divisorias o macilizar vigas y columnas para cubierta. Realizar intervención de humedad.', 'Iris Fernandez', '1192894340', '{"form_num": "83", "pagina_1": {"sector": "Urbano", "telefono": "3122081011", "direccion": "Cra 2 # 15B-84", "documento": "29398080", "municipio": "Yumbo", "fecha_hora": "13 Agosto", "coordenadas": "Lat: 3°35''2\"N, Long: 76°29''10\"O", "barrio_vereda": "Fray Peña", "relacion_inmueble": "Propietario(a)", "informacion_evento": "Se percibió el sismo, daños aparecieron durante o después del evento.", "persona_entrevistada": "Leidy Montes", "caracteristicas_inmueble": {"tipo": "Casa unifamiliar", "pisos": 1, "cubierta": "Teja barro", "material": ["Mampostería", "Concreto"], "antiguedad": "50 años", "area_aprox": "165 m²"}}, "pagina_2": {"senales_visibles": ["Grietas diagonales en muros", "Desplazamiento de elementos", "Caída de elementos de fachada", "Caída de cielo raso"], "descripcion_ocurrido": "Fractura en paredes, por el sistema de carga parecen estructurales; adicional, hay desprendimiento de losa en el frente de la casa, caída del techo y cielo de la parte delantera.", "evaluacion_visual_daños": {"vigas": "Sin daño", "columnas": "Sin daño", "cubierta": "Grave", "escaleras": "Sin daño", "cielo_raso": "Leve", "pisos_enchapes": "Leve", "muros_portantes": "Moderado", "placa_entrepiso": "Sin daño", "cimentacion_piso": "Leve", "muros_divisorios": "Leve", "puertas_ventanas": "Leve", "fachada_cerramiento": "Moderado"}, "ubicacion_descripcion_daños": "Los daños se presentan en la zona frontal de la casa, al ser larga, supo se afectó la cubierta que no había sido reformada."}, "pagina_3": {"condiciones_riesgo": {"tipos_riesgo": ["Riesgo de caída de elementos", "Riesgo por elementos estructurales aparentemente comprometidos"], "ubicacion_riesgo": "Zona frontal de la casa, apoyo de cubiertas, muros posiblemente que actúan cargando.", "restringir_acceso": "No", "suspender_uso_sede": "No"}, "clasificacion_preliminar": "Afectaciones estructurales o funcionales parciales", "justificacion_afectacion": "Existen afectaciones parciales para el ingreso de la vivienda y transitar en la zona delantera de la casa.", "elementos_no_estructurales": {"pisos": "Afectado", "puertas": "Bueno", "barandas": "N/A", "enchapes": "N/A", "ventanas": "Afectado", "cubiertas": "Grave", "cielo_rasos": "Afectado", "muros_divisorios": "Grave"}}, "pagina_4": {"bienes_afectados": {"herramientas": "Sin daño", "muebles_enseres": "Sin daño", "electrodomesticos": "Sin daño"}, "vulnerabilidades": ["Adulto mayor solo/dependiente"], "composicion_hogar": {"total_personas": 1}, "observaciones_concepto": {"evaluador": {"cargo": "Contratista - Ing. Civil", "nombre": "Iris Fernandez", "documento": "1192894340"}, "entrevistada": {"nombre": "Leidy Montes", "telefono": "3122081011", "documento": "29398080"}, "recomendaciones": "Demoler losa, intervenir la cubierta que está en madera y teja de barro, reforzar paredes divisorias o macilizar vigas y columnas para cubierta. Realizar intervención de humedad.", "observaciones_generales": "Caída de cubierta, caja antigua, daño en paredes, losa suelta, se recomienda evitar la zona de la entrada hasta intervención."}, "necesidades_prioritarias": ["Reparación de cubierta, es un adulto mayor."], "evaluacion_socioeconomica": {"condicion": ["Adulto mayor"], "ingreso_principal": "Ayuda/subsidio (los hijos brindan ayuda 4 hijos)"}}}', '2026-08-15 16:58:51.452427');
INSERT INTO public.edhas_evaluaciones VALUES (2, '65013a02-7b5d-4da8-810b-e3e724834b99', 'EDHAS-20260813-002', '2026-08-13', 'Margarita Fernandez', '29940795', '3127867072', 'Cra 1A # 11-25 / 1-27', 'Bolívar', 'Comercio', 'Baja', 'Afectaciones menores', 'Se encuentra cubierta derrumbada, muro desprendido y con posible caída a los predios vecinos.', 'Se requiere la demolición de la barda perimetral ubicada en el 3er piso, posible afectación a vecinos.', 'Iris Fernandez', '1192894340', '{"form_num": "84", "pagina_1": {"sector": "Urbano", "telefono": "3127867072", "direccion": "Cra 1A # 11-25 / 1-27", "documento": "29940795", "municipio": "Yumbo", "fecha_hora": "13/08/26 2:00 pm", "barrio_vereda": "Bolívar", "relacion_inmueble": "Arrendatario(a) / Familiar", "informacion_evento": "Caída de elementos, daños aparecieron durante o después del evento.", "persona_entrevistada": "Margarita Fernandez", "caracteristicas_inmueble": {"tipo": "Comercio", "pisos": 3, "cubierta": "Placa de concreto / Steel deck", "material": ["Mampostería", "Concreto", "Material liviano", "Mixto"], "antiguedad": "16 años", "area_aprox": "141 m²"}}, "pagina_2": {"senales_visibles": ["Desplazamiento de elementos"], "descripcion_ocurrido": "A partir del sismo se presenta desprendimiento de la cubierta, y se evidencia falla en el sistema constructivo, la barda perimetral del cerramiento de la terraza (3er piso) se encuentra suelta.", "evaluacion_visual_daños": {"cubierta": "Leve", "muros_divisorios": "Moderado"}, "ubicacion_descripcion_daños": "Terraza 3er piso, barda perimetral."}, "pagina_3": {"condiciones_riesgo": {"tipos_riesgo": ["Riesgo de caída de elementos"], "ubicacion_riesgo": "Riesgo caída de muro perimetral en ladrillo en el área de la terraza."}, "clasificacion_preliminar": "Afectaciones menores", "justificacion_afectacion": "Tercer piso.", "elementos_no_estructurales": {"cerramientos": "Afectado", "muros_divisorios": "Grave"}}, "pagina_4": {"bienes_afectados": {}, "vulnerabilidades": [], "composicion_hogar": {"total_personas": 0}, "observaciones_concepto": {"evaluador": {"cargo": "Ing. Civil", "nombre": "Iris Fernandez", "documento": "1192894340"}, "entrevistada": {"nombre": "Margarita Fernandez", "telefono": "3127867072", "documento": "29940795"}, "recomendaciones": "Se requiere la demolición de la barda perimetral ubicada en el 3er piso, posible afectación a vecinos.", "observaciones_generales": "Se encuentra cubierta derrumbada, muro desprendido y con posible caída a los predios vecinos."}, "necesidades_prioritarias": ["N/A"], "evaluacion_socioeconomica": {}}}', '2026-08-15 16:58:51.452427');
INSERT INTO public.edhas_evaluaciones VALUES (3, '6306c4a5-884b-4194-a0c7-1d63b0cd79a2', 'EDHAS-20260813-003', '2026-08-13', 'Julio Cesar Apolindor Sanchez', '16446381', '3053815849', 'Cra 6 # 13-35', 'Bolívar', 'Edificio Aptos - Aporticado', 'Baja', 'Afectaciones menores', 'Se observan daños no estructurales, se recomienda reparación de la escalera con reforzamiento estructural.', 'Un entibado correspondiente para no afectar el paso, reparar muros y/o demoler los que sí requieren intervención.', 'Iris Dahiana J.', '1192894340', '{"form_num": "85", "pagina_1": {"sector": "Urbano", "telefono": "3053815849", "direccion": "Cra 6 # 13-35", "documento": "16446381", "municipio": "Yumbo", "fecha_hora": "13 Agosto 26", "barrio_vereda": "Bolívar", "relacion_inmueble": "Propietario(a)", "informacion_evento": "Se percibió el sismo, daños aparecieron durante o después del evento.", "persona_entrevistada": "Julio Cesar Apolindor Sanchez", "caracteristicas_inmueble": {"tipo": "Edificio Aptos - Aporticado", "pisos": 4, "cubierta": "Placa de concreto", "material": ["Mampostería", "Concreto"], "antiguedad": "25 años", "area_aprox": "170 m²"}}, "pagina_2": {"senales_visibles": ["Grietas diagonales en muros"], "descripcion_ocurrido": "Terremoto del 10 de agosto causa daños, desprendimiento muro escalera, daños no estructurales, se recomienda mejorar anclaje y reforzar la nueva escalera, debe demoler el muro de la escalera, muros internos de aptos, reparar y otros volver a hacer.", "evaluacion_visual_daños": {"escaleras": "Moderado", "muros_divisorios": "Moderado"}, "ubicacion_descripcion_daños": "Daños en muros no estructurales y escaleras (Piso 1, 2...)"}, "pagina_3": {"condiciones_riesgo": {"tipos_riesgo": ["Riesgo de caída de elementos"], "ubicacion_riesgo": "En el área de la escalera se presenta posible desprendimiento del muro que colinda con el baño."}, "clasificacion_preliminar": "Afectaciones menores", "justificacion_afectacion": "Escalera y muros de aptos.", "elementos_no_estructurales": {"barandas": "Afectado", "muros_divisorios": "Afectado"}}, "pagina_4": {"bienes_afectados": {"electrodomesticos": "Pérdida total (1 televisor)"}, "vulnerabilidades": [], "composicion_hogar": {"total_personas": 0}, "observaciones_concepto": {"evaluador": {"cargo": "Ing. Civil", "nombre": "Iris Dahiana J.", "documento": "1192894340"}, "entrevistada": {"nombre": "Julio Cesar Apolindor Sanchez", "telefono": "3053815849", "documento": "16446381"}, "recomendaciones": "Un entibado correspondiente para no afectar el paso, reparar muros y/o demoler los que sí requieren intervención.", "observaciones_generales": "Se observan daños no estructurales, se recomienda reparación de la escalera con reforzamiento estructural."}, "necesidades_prioritarias": ["N/A"], "evaluacion_socioeconomica": {}}}', '2026-08-15 16:58:51.452427');
INSERT INTO public.edhas_evaluaciones VALUES (4, 'e0990b25-fc69-4b35-828b-8dbba11dc138', 'EDHAS-20260813-004', '2026-08-13', 'Maria Ludivia Osorio Murillo', '1118283542', '3113568419', 'calle 13BN # 15N - 51', 'Pizarro', 'Casa unifamiliar', 'Baja', 'Afectaciones menores', 'No hay afectación estructural, se recomienda demolición parcial y correctamente muros de mampostería para evitar caída de estos.', 'Se recomienda evitar caída o desprendimiento de muros no estructurales, evitar habitar cuarto afectado.', 'Iris Fernandez', '1192894340', '{"form_num": "86", "pagina_1": {"sector": "Urbano", "telefono": "3113568419", "direccion": "calle 13BN # 15N - 51", "documento": "1118283542", "municipio": "Yumbo", "fecha_hora": "13 Agosto 26", "barrio_vereda": "Pizarro", "relacion_inmueble": "Propietario(a)", "informacion_evento": "Se percibió el sismo, daños aparecieron durante o después del evento.", "persona_entrevistada": "Maria Ludivia Osorio Murillo", "caracteristicas_inmueble": {"tipo": "Casa unifamiliar", "pisos": 3, "cubierta": "Metálica", "material": ["Mampostería", "Concreto", "Material liviano", "Mixto"], "antiguedad": "22 - 10 años (Inviyumbo reconstruyó)", "area_aprox": "60 m²"}}, "pagina_2": {"senales_visibles": ["Grietas diagonales en muros"], "descripcion_ocurrido": "Se encuentran varios muros no estructurales fracturados, muy comprometidos, algunos deben demolerse y volverse a realizar. No hay afectación en piso 1 y 3, solo en el segundo piso.", "evaluacion_visual_daños": {"muros_divisorios": "Moderado"}, "ubicacion_descripcion_daños": "Segundo piso."}, "pagina_3": {"condiciones_riesgo": {"tipos_riesgo": ["Riesgo de caída de elementos"], "ubicacion_riesgo": "Segundo piso"}, "clasificacion_preliminar": "Afectaciones menores", "justificacion_afectacion": "Caída de elementos de mampostería.", "elementos_no_estructurales": {"cielo_rasos": "N/A", "muros_divisorios": "Afectado"}}, "pagina_4": {"bienes_afectados": {}, "vulnerabilidades": [], "composicion_hogar": {"total_personas": 2}, "observaciones_concepto": {"evaluador": {"cargo": "Contratista", "nombre": "Iris Fernandez", "documento": "1192894340"}, "entrevistada": {"nombre": "Maria Ludivia Osorio Murillo", "telefono": "3113568419", "documento": "1118283542"}, "recomendaciones": "Se recomienda evitar caída o desprendimiento de muros no estructurales, evitar habitar cuarto afectado.", "observaciones_generales": "No hay afectación estructural, se recomienda demolición parcial y correctamente muros de mampostería para evitar caída de estos."}, "necesidades_prioritarias": ["N/A. Vivienda propia, no requieren prioridad."], "evaluacion_socioeconomica": {"ingreso_principal": "Independiente"}}}', '2026-08-15 17:15:06.153772');
INSERT INTO public.edhas_evaluaciones VALUES (5, '14bfa778-7f8a-4efd-a645-38943e81b26f', 'EDHAS-20260813-005', '2026-08-13', 'Mariela Benavidez', '25714867', '3137016872', 'Cll 14BN 15-35', 'Guadalupe', 'Bifamiliar', 'Media', 'Afectaciones menores', 'El primer piso de la vivienda está en buen estado, el segundo tiene afectaciones en la mampostería.', 'Retirar ladrillos sueltos y realizar de nuevo la correcta instalación de ellos, adicional monitorear ladrillos fracturados en puertas por riesgo de caída.', 'Iris Fernandez', '1192894340', '{"form_num": "90", "pagina_1": {"sector": "Urbano", "telefono": "3044530516", "direccion": "Carrera 12C # 23-34", "documento": "17041291", "municipio": "Yumbo", "fecha_hora": "13/08/2026 4:30", "barrio_vereda": "La Estancia", "relacion_inmueble": "Arrendatario(a)", "informacion_evento": "Se percibió el sismo.", "persona_entrevistada": "Rafael Faudito Ruiz", "caracteristicas_inmueble": {"tipo": "No especificado / Mixto", "pisos": 3, "cubierta": "Metálica", "material": ["Mampostería", "Concreto", "Mixto"], "antiguedad": "No registra", "area_aprox": "No registra"}}, "pagina_2": {"senales_visibles": ["Grietas nuevas en elementos estructurales", "Grietas diagonales en muros", "Grietas/fisuras en vigas", "Desprendimiento de concreto", "Hundimientos/asentamientos visibles", "Caída de elementos de fachada"], "descripcion_ocurrido": "Es una construcción hecha en estructura metálica pero revundada, con urgencia se recomienda desocupar y entrar a demoler.", "evaluacion_visual_daños": {"vigas": "Leve", "columnas": "Leve", "cubierta": "Leve", "escaleras": "Leve", "cielo_raso": "Leve", "pisos_enchapes": "Leve", "muros_portantes": "Leve", "placa_entrepiso": "Leve", "cimentacion_piso": "Leve", "muros_divisorios": "Leve", "puertas_ventanas": "Leve", "fachada_cerramiento": "Leve"}, "ubicacion_descripcion_daños": "Existen materiales de diferente tipo oxidados (perfiles metálicos) y el concreto muy regular."}, "pagina_3": {"condiciones_riesgo": {"tipos_riesgo": ["Riesgo por elementos estructurales aparentemente comprometidos", "Riesgo en cubierta", "Riesgo en escaleras", "Riesgo en muros/cerramientos"], "ubicacion_riesgo": "Estructural general", "restringir_acceso": "Sí, parcialmente", "suspender_uso_sede": "Sí"}, "clasificacion_preliminar": "Riesgo inminente de colapso", "justificacion_afectacion": "Estructura metálica en muy mal estado, materiales oxidados.", "elementos_no_estructurales": {"pisos": "Bueno", "puertas": "Bueno", "barandas": "Bueno", "enchapes": "Bueno", "ventanas": "Bueno", "cubiertas": "Bueno", "cielo_rasos": "Bueno", "muros_divisorios": "Afectado"}}, "pagina_4": {"bienes_afectados": {}, "vulnerabilidades": [], "composicion_hogar": {"total_personas": 0}, "observaciones_concepto": {"evaluador": {"cargo": "Arquitecto", "nombre": "Oscar E. Courrau", "documento": "19478180"}, "entrevistada": {"nombre": "Rafael Faudito Ruiz", "telefono": "3044530516", "documento": "17041291"}, "recomendaciones": "Desocupar y entrar a demoler.", "observaciones_generales": "Construcción en estructura metálica deficiente. Urge desocupar y demoler."}, "necesidades_prioritarias": ["Estructura metálica en muy mal estado!"], "evaluacion_socioeconomica": {}}}', '2026-08-15 17:15:06.153772');
