INSERT INTO public.edhas_evaluaciones VALUES (16, '89ad8c08-0f35-40f7-8a87-719037f7834b', 'EDHAS-20260814-013', '2026-08-14', 'Luis Horacio Gil Valencia', '17041291', '3148207496', 'Cll 6A # 18D-04', 'Panorama', 'Casa unifamiliar', 'Alta', 'Afectaciones estructurales o funcionales parciales', 'Se evidencian daños en fisuras de las columnas y vigas de amarración, la escalera está suelta, la del 2do piso y la del patio, se evidencian fracturas en las paredes, asentamiento en la parte de atrás.', 'Apuntalamiento y reforzamiento estructural.', 'Iris D. Semanate', '1192894340', '{"form_num": "151", "pagina_1": {"sector": "Urbano", "telefono": "3148207496", "direccion": "Cll 6A # 18D-04", "documento": "17041291", "municipio": "Yumbo", "fecha_hora": "14/08/2026 4:40 pm", "barrio_vereda": "Panorama", "relacion_inmueble": "Propietario(a)", "informacion_evento": "Se percibió el sismo, evacuación preventiva, caída de elementos.", "persona_entrevistada": "Luis Horacio Gil Valencia", "caracteristicas_inmueble": {"tipo": "Casa unifamiliar", "pisos": 2, "cubierta": "Placa de concreto", "material": ["Mampostería", "Concreto"], "antiguedad": "28 años", "area_aprox": "91 m²"}}, "pagina_2": {"senales_visibles": ["Grietas nuevas en elementos estructurales", "Grietas diagonales en muros", "Grietas/fisuras en columnas", "Grietas/fisuras en vigas"], "descripcion_ocurrido": "Se evidencia afectación dentro del sismo presentado del 10 de agosto, hay afectación en la vivienda en la parte estructural, cimentación y columnas en la parte que transmite al piso.", "evaluacion_visual_daños": {"vigas": "Leve", "columnas": "Moderado", "escaleras": "Leve", "cimentacion_piso": "Moderado", "muros_divisorios": "Moderado", "fachada_cerramiento": "Leve"}, "ubicacion_descripcion_daños": "En las columnas y vigas de cimentación se evidencian fracturas en la parte estructural, se evidencian que han sido realizadas con balastro."}, "pagina_3": {"condiciones_riesgo": {"tipos_riesgo": ["Riesgo por elementos estructurales aparentemente comprometidos", "Riesgo en escaleras", "Riesgo en muros/cerramientos"], "ubicacion_riesgo": "Riesgo en elementos de columna y vigas que alimentan la casa, escalera hacia el patio y 2do piso.", "restringir_acceso": "Sí, parcialmente"}, "clasificacion_preliminar": "Afectaciones estructurales o funcionales parciales", "justificacion_afectacion": "En evidencia de otro sismo podría fracturar elementos que cimentan la parte trasera de la casa.", "elementos_no_estructurales": {"pisos": "Afectado", "tanques": "Afectado", "cerramientos": "Afectado", "muros_divisorios": "Afectado"}}, "pagina_4": {"bienes_afectados": {}, "vulnerabilidades": ["Zona con amenaza conocida", "No cuenta con otra vivienda disponible", "Persona con discapacidad", "Adulto mayor solo/dependiente", "Padres subsidiados (adultos mayores), hijo con trabajo instable"], "composicion_hogar": {"total_personas": 1}, "observaciones_concepto": {"evaluador": {"cargo": "Ing. Civil", "nombre": "Iris D. Semanate", "documento": "1192894340"}, "entrevistada": {"nombre": "Luis Horacio Gil Valencia", "telefono": "3148207496", "documento": "17041291"}, "recomendaciones": "Apuntalamiento y reforzamiento estructural.", "observaciones_generales": "Se evidencian daños en fisuras de las columnas y vigas de amarración, la escalera está suelta, la del 2do piso y la del patio, se evidencian fracturas en las paredes, asentamiento en la parte de atrás."}, "necesidades_prioritarias": ["Ayuda rehabilitación estructural vivienda", "Atención social, personas dependen de 1 hijo sin trabajo fijo"], "evaluacion_socioeconomica": {"condicion": ["Adulto mayor", "Persona con discapacidad"], "ingreso_principal": "ayuda/subsidio"}}}', '2026-08-15 17:29:31.960313');
INSERT INTO public.edhas_evaluaciones VALUES (17, 'ff7277ae-3197-4862-a3c5-49f9224620d1', 'EDHAS-20260814-014', '2026-08-14', 'Jhon Fonseca', '16463029', '3206075028', 'Calle 6 # 16K-97', 'Panorama', 'Bifamiliar', 'Media', 'Afectaciones menores', 'Se evidencia de la situación del sismo movimiento en las paredes de la vivienda, afectando mampostería que actúa como estructural por falta de columnas, se han apuntalado todas las áreas de la casa, se recomienda reforzamiento estructural en el 1er piso.', 'Apuntalamiento y reforzamiento.', 'Iris D. Semanate', '1192894340', '{"form_num": "152", "pagina_1": {"sector": "Urbano", "telefono": "3206075028", "direccion": "Calle 6 # 16K-97", "documento": "16463029", "municipio": "Yumbo", "fecha_hora": "14 Agosto-26", "barrio_vereda": "Panorama", "relacion_inmueble": "Propietario(a)", "informacion_evento": "Se percibió el sismo, evacuación preventiva, caída de elementos.", "persona_entrevistada": "Jhon Fonseca", "caracteristicas_inmueble": {"tipo": "Bifamiliar", "pisos": 2, "cubierta": "Fibrocemento", "material": ["Mampostería", "Concreto"], "antiguedad": "13 años", "area_aprox": "90 m²"}}, "pagina_2": {"senales_visibles": ["Grietas diagonales en muros", "Daño en escaleras"], "descripcion_ocurrido": "A partir del sismo del 10 de agosto se evidencian fracturas en la mampostería no estructural de la vivienda, sin embargo, faltando elementos estructurales (columna) actúan como portantes.", "evaluacion_visual_daños": {"vigas": "Leve", "escaleras": "Leve", "muros_divisorios": "Moderado", "fachada_cerramiento": "Leve"}, "ubicacion_descripcion_daños": "Grietas y desprendimiento en muros."}, "pagina_3": {"condiciones_riesgo": {"tipos_riesgo": ["Riesgo de caída de elementos"], "ubicacion_riesgo": "En el segundo piso se perciben columnas que no se reflejan en el primer piso, por tanto se requiere reforzamiento.", "restringir_acceso": "Sí, totalmente"}, "clasificacion_preliminar": "Afectaciones menores", "justificacion_afectacion": "Puede tener riesgo de caída las paredes, afectar a las personas de la vivienda.", "elementos_no_estructurales": {"barandas": "Afectado", "muros_divisorios": "Grave"}}, "pagina_4": {"bienes_afectados": {}, "vulnerabilidades": [], "composicion_hogar": {"total_personas": 0}, "observaciones_concepto": {"evaluador": {"cargo": "Ing. Civil", "nombre": "Iris D. Semanate", "documento": "1192894340"}, "entrevistada": {"nombre": "Jhon Fonseca", "telefono": "3206075028", "documento": "16463029"}, "recomendaciones": "Apuntalamiento y reforzamiento.", "observaciones_generales": "Se evidencia de la situación del sismo movimiento en las paredes de la vivienda, afectando mampostería que actúa como estructural por falta de columnas, se han apuntalado todas las áreas de la casa, se recomienda reforzamiento estructural en el 1er piso."}, "necesidades_prioritarias": [], "evaluacion_socioeconomica": {}}}', '2026-08-15 17:29:31.960313');
INSERT INTO public.edhas_evaluaciones VALUES (18, 'f94e7af8-c265-4c94-b8ad-27d23e9c0d9d', 'EDHAS-20260814-015', '2026-08-14', 'Ana Milena Lerma', '31488552', '3013146551', 'Cra 18 # 6-15', 'Panorama', 'Bifamiliar', 'Media', 'Afectaciones menores', 'Del sismo se desprendieron 4 paredes no estructurales, la propietaria realizó reparación.', 'Monitoreo y revisión de acabados.', 'Iris D. Semanate', '1192894340', '{"form_num": "153", "pagina_1": {"sector": "Urbano", "telefono": "3013146551", "direccion": "Cra 18 # 6-15", "documento": "31488552", "municipio": "Yumbo", "fecha_hora": "14/10/2026 5:25 pm", "barrio_vereda": "Panorama", "relacion_inmueble": "Propietario(a)", "informacion_evento": "Se percibió el sismo, daños aparecieron durante o después del evento.", "persona_entrevistada": "Ana Milena Lerma", "caracteristicas_inmueble": {"tipo": "Bifamiliar", "pisos": 2, "cubierta": "Fibrocemento", "material": ["Mampostería", "Concreto", "Estructura metálica"], "antiguedad": "18 años", "area_aprox": "48 m²"}}, "pagina_2": {"senales_visibles": ["Grietas diagonales en muros", "Daño en escaleras"], "descripcion_ocurrido": "Se evidencia movimiento en la estructura del sismo del 10 de agosto, se desprendieron 4 muros no estructurales en ambos pisos.", "evaluacion_visual_daños": {"escaleras": "Leve", "muros_divisorios": "Moderado"}, "ubicacion_descripcion_daños": "Daño en muros no estructurales, reparados por la propietaria, requiere reunión."}, "pagina_3": {"condiciones_riesgo": {"tipos_riesgo": ["Riesgo de caída de elementos", "Riesgo en escaleras"], "ubicacion_riesgo": "Riesgo caída escalera, la propietaria realizó la reparación", "restringir_acceso": "No"}, "clasificacion_preliminar": "Afectaciones menores", "justificacion_afectacion": "Muros no estructurales.", "elementos_no_estructurales": {"ventanas": "Afectado", "muros_divisorios": "Afectado"}}, "pagina_4": {"bienes_afectados": {}, "vulnerabilidades": ["Niños/NNA con necesidad de protección", "Pérdida de herramientas de trabajo", "Persona conflicto armado víctima", "Emprendimiento"], "composicion_hogar": {"total_personas": 0}, "observaciones_concepto": {"evaluador": {"cargo": "Ing. Civil", "nombre": "Iris D. Semanate", "documento": "1192894340"}, "entrevistada": {"nombre": "Ana Milena Lerma", "telefono": "3013146551", "documento": "31488552"}, "recomendaciones": "Monitoreo y revisión de acabados.", "observaciones_generales": "Del sismo se desprendieron 4 paredes no estructurales, la propietaria realizó reparación."}, "necesidades_prioritarias": ["Atención social"], "evaluacion_socioeconomica": {"ingreso_estable": false, "ingreso_principal": "independiente"}}}', '2026-08-15 17:29:31.960313');
INSERT INTO public.edhas_evaluaciones VALUES (19, '0f6f960d-2755-4822-a708-e0dc54dea5c7', 'EDHAS-20260814-016', '2026-08-14', 'Liliana Manzano Betancourt', '31471943', '318284765', 'Cra 18A con calle 15 Esquina 15-76', 'Juan Pablo II', 'Apartamento (3 apartamentos)', 'Media', 'Afectaciones estructurales o funcionales parciales', 'Se observan errores constructivos en los 2do y 3er pisos, que permite que la estructura haya sido afectada por el sismo.', 'Se recomienda reforzamiento estructural desde el segundo al tercer piso, demolición de muro en fachada suelto, reparación con reforzamiento y anclaje para los muros.', 'Iris Dahiana J.', '1192894340', '{"form_num": "154", "pagina_1": {"sector": "Urbano", "telefono": "318284765", "direccion": "Cra 18A con calle 15 Esquina 15-76", "documento": "31471943", "municipio": "Yumbo", "fecha_hora": "14 Agosto 26", "coordenadas": "Lat: 3°34''10\"N, Long: 76°29''17\"O", "barrio_vereda": "Juan Pablo II", "relacion_inmueble": "Propietario(a)", "informacion_evento": "Se percibió el sismo, evacuación preventiva, caída de elementos, daños aparecieron durante o después del evento.", "persona_entrevistada": "Liliana Manzano Betancourt", "caracteristicas_inmueble": {"tipo": "Apartamento (3 apartamentos)", "pisos": 3, "cubierta": "Metálica", "material": ["Mampostería", "Concreto", "Columnas, ladrillos no confinados"], "antiguedad": "25 años", "area_aprox": "84 m²"}}, "pagina_2": {"senales_visibles": ["Grietas diagonales en muros"], "descripcion_ocurrido": "Se evidencian errores constructivos en la vivienda que a través del sismo presentado el 10 de agosto han afectado al predio en la mampostería, que al no tener confinamiento y no evidenciarse vigas en el 3er piso obligan a la mampostería.", "evaluacion_visual_daños": {"columnas": "Moderado", "escaleras": "Moderado", "muros_portantes": "Moderado", "muros_divisorios": "Moderado", "fachada_cerramiento": "Moderado"}, "ubicacion_descripcion_daños": "En segundo y tercer piso. Falla constructiva (no se evidencia entre 3er piso y 2do), daño en muro estructural."}, "pagina_3": {"condiciones_riesgo": {"tipos_riesgo": ["Riesgo de caída de elementos", "Riesgo en escaleras"], "ubicacion_riesgo": "Caída y desprendimiento de mampostería que no está confinada, escaleras con mal diseño e instalación. Piso 2, persona adulto mayor.", "restringir_acceso": "Sí, parcialmente", "suspender_uso_sede": "Sí"}, "clasificacion_preliminar": "Afectaciones estructurales o funcionales parciales", "justificacion_afectacion": "Afectaciones por errores constructivos, mampostería sin confinamiento, falta de anclaje y falla en la pega.", "elementos_no_estructurales": {"barandas": "Afectado", "muros_divisorios": "Grave"}}, "pagina_4": {"bienes_afectados": {}, "vulnerabilidades": ["Zona con amenaza conocida", "Colindancia con vía intermunicipal"], "composicion_hogar": {"total_personas": 1}, "observaciones_concepto": {"evaluador": {"cargo": "Ing. Civil", "nombre": "Iris Dahiana J.", "documento": "1192894340"}, "entrevistada": {"nombre": "Liliana Manzano Betancourt", "telefono": "318284765", "documento": "31471943"}, "recomendaciones": "Se recomienda reforzamiento estructural desde el segundo al tercer piso, demolición de muro en fachada suelto, reparación con reforzamiento y anclaje para los muros.", "observaciones_generales": "Se observan errores constructivos en los 2do y 3er pisos, que permite que la estructura haya sido afectada por el sismo."}, "necesidades_prioritarias": [], "evaluacion_socioeconomica": {"condicion": ["Adulto mayor"]}}}', '2026-08-15 17:36:55.926416');
