INSERT INTO public.rufe_formularios VALUES (1, '5471cea8-e691-4e9c-9fb0-acf0df431676', '6', 'Santa Ines', 'MEDIA', 'Animales - 2 perros', 'Vivienda construida en bahareque, hace mas de 50 años, con desprendimientos en muros y cubierta parcialmente colapsada. Prioridad: MEDIA');
INSERT INTO public.rufe_formularios VALUES (2, '92a97521-f629-4fa9-a4eb-e9561a5c95a7', '7', 'Montañitas', 'MEDIA', '10 Perros', 'Vivienda construida en bahareque, con pequeños desprendimientos en los muros. No existe riesgo inminente. Prioridad: MEDIA');
INSERT INTO public.rufe_formularios VALUES (3, '2a26b947-7a81-4cf5-a346-2b61153d09e7', '8', 'Santa Ines', 'MEDIA', '5 Gatos, 3 Perros', 'Vivienda en material con fisuras en el piso, y muros de mamposteria colapsados. Prioridad: MEDIA');
INSERT INTO public.rufe_formularios VALUES (4, '6b438c3a-618b-43a1-bd5f-8254da8429dc', '9', 'Montañitas', 'MEDIA', '1 Perro, 1 Gato, 2 Pollos', 'Vivienda colapsada de bahareque. parcialmente en 2 habitaciones. Prioridad: MEDIA');
INSERT INTO public.rufe_formularios VALUES (5, '2fbe0000-11dd-4c26-9ea9-c36e507676b3', '10', 'Santa Ines', 'MEDIA', 'Animales - 6 perros', 'Vivienda construida en material, con elementos estructurales superiores fracturados. Posible demolicion. Prioridad: MEDIA');
INSERT INTO public.rufe_formularios VALUES (6, '7f44b3e3-28c9-40fb-845e-aa28d3a896de', '12', 'Santa Ines', 'BAJA', 'No registra', 'Vivienda en prefabricado, con fisuras en las juntas de los modulos. Prioridad: BAJA');
INSERT INTO public.rufe_formularios VALUES (7, '151a92da-7031-4657-bd6b-8cc8707d2e07', '13', 'Santa Ines', 'BAJA', '1 Perro - 30 Gallinas', 'Vivienda construida en madera con cubierta colapsada parcialmente. Prioridad: BAJA');
INSERT INTO public.rufe_formularios VALUES (8, 'fbb20b03-9ae4-44a7-9531-989cf2517cd8', '1', 'Santa Ines', 'ALTA', 'No registra', 'Vivienda en bahareque, colapsada en un 70%. No es habitable. Prioridad: ALTA');
INSERT INTO public.rufe_formularios VALUES (9, 'e4c42014-7d73-4e31-8091-95039b9d25fe', '2', 'Santa Ines', 'ALTA', 'No registra', 'Vivienda construida en pre-fabricado, colapsada en un 80% en paredes. Prioridad: ALTA');
INSERT INTO public.rufe_formularios VALUES (10, 'd854053f-6053-4db4-957c-521aba71ecc1', '3', 'Santa Ines', 'MEDIA', 'Animales - 5 Perros', 'Vivienda construida en bahareque, cubierta comprometida. Prioridad: MEDIA');
INSERT INTO public.rufe_formularios VALUES (11, 'ab6bb81b-7e1d-46bd-ad0b-fef99ccc00ae', '4', 'Santa Ines', 'ALTA', 'No registra', 'Vivienda construida de material, colapsada en un 70%. Baños destruidos. Prioridad: ALTA');
INSERT INTO public.rufe_formularios VALUES (12, 'cb1f5c02-23a2-411f-aed3-5d8cd9f55a3f', '5', 'Santa Ines', 'MEDIA', 'Animales: - 20 Gatos - 2 perros', 'Vivienda construida en bahareque con su cubierta colapsada en gran parte. Prioridad: MEDIA');
INSERT INTO public.rufe_formularios VALUES (13, '5c4689a7-3b64-450e-aa1c-f1d6914b7a69', '13', 'Santa Ines', 'BAJA', '1 Perro - 30 Gallinas', 'Vivienda construida en madera con cubierta colapsada parcialmente. Es habitable completamente, se recomienda hacer seguimiento a la estructura. Prioridad: BAJA.');
INSERT INTO public.rufe_formularios VALUES (14, 'cdc48f37-3300-44cd-ae0c-f149cbb8e90b', '11', 'Santa Ines', 'BAJA', '2 Perros - 1 Gato', 'Vivienda construida en material, con muros de mamposteria fisurados. Los elementos estructurales estan en buen estado. Vivienda habitable, sin riesgo latente.');
INSERT INTO public.rufe_formularios VALUES (15, '6cb6e827-fc35-4833-9d06-8ea45bb40c6e', '14', 'Mulalo', 'MEDIA', '1 gatico', 'Vivienda de un piso. Fisuras en muros superficiales. Cubierta con desplazamientos en los apoyos, probabilidad de desplome. Medio habitable pero requiere reparar apoyos de la cubierta.');
INSERT INTO public.rufe_formularios VALUES (16, 'aed6368a-2cc6-4497-87a1-1e6a4831a5ff', '15', 'Mulalo', 'BAJA', '1 gata no esterilizada - 9 años', 'Vivienda Unifamiliar. No presentar daños estructurales.');
INSERT INTO public.rufe_formularios VALUES (17, 'a232405e-cc03-4e08-8314-e550006bbf09', '16', 'Mulalo', 'BAJA', 'Dos perras y solo una esta esterilizada', 'Vivienda unifamiliar. Es una vivienda Prefabricada. Sin Afectaciones Estructurales.');
INSERT INTO public.rufe_formularios VALUES (18, 'c88c4821-7ff3-4c14-b03d-0aa22dcf491e', '17', 'Mulalo', 'BAJA', 'No reporta', 'Vivienda unifamiliar. Daños superficiales en ceramica y desprendimiento del anden parte externa de la casa. Muros en perfecto estado.');
INSERT INTO public.rufe_formularios VALUES (19, '85abd49e-eac3-49e0-85d2-69802d92859c', '18', 'Mulalo', 'BAJA', 'Dos perros', 'Fisuras superficiales que afectan el acabado de los muros.');
INSERT INTO public.rufe_formularios VALUES (20, '734a543a-c5ee-4870-bbef-c0ce85d00a58', '19', 'Mulalo', 'MEDIA', '1 gata (8 años), 1 perro (2 años), 1 perrita (1 año)', 'Daños superficiales en mampostería. Falta de viguetas y columnetas de confinamiento.');
INSERT INTO public.rufe_formularios VALUES (21, '0003f627-acef-4b04-a226-0653dee3fd97', '20', 'Mulalo', 'MEDIA', '1 gata esterilizada - 5 años', 'Daños superficiales en repello y en mamposteria. Vivienda no cuenta con vigas de Amarres para muro.');
INSERT INTO public.rufe_formularios VALUES (23, 'eb9bca7c-6540-4c6a-a776-c54e45ac8189', '22', 'Paso de la torre', 'MEDIA', '2 gatos, 2 perros', 'Vivienda de dos pisos. Vivienda habitable. Desprendimiento de enchape en cocina primer piso. Fisuras superficiales en placa superior y muros. Losa en bloque lon.');
INSERT INTO public.rufe_formularios VALUES (24, '170820af-3d9f-409c-8551-88c8b349e5c1', '23', 'Paso de la torre', 'ALTA', '1 perro no esterilizado (11 meses), 1 perrita esterilizada (4 años), 2 gatos esterilizados (1 año - 18 meses), 1 gatito sin esterilizar (3 meses)', 'Vivienda unifamiliar. Uno de los adultos mayores tienen movilidad reducida (silla de ruedas) y discapacidad cognitiva. Vivienda sin sistemas de pórtico lo que ocasiona que graves daños en muros y separaciones y grietas por alto grado de colapso.');
INSERT INTO public.rufe_formularios VALUES (25, '0d2b60c2-2da6-4ff1-8af0-28bcf3a07769', '24', 'Paso de la torre', 'ALTA', 'Un perro esterilizado (2 años), una perra esterilizada (9 años)', 'Vivienda unifamiliar. Daños estructurales en muros. Daños estructurales en cubierta. Desplazamientos de pisos internos. Desplazamientos de cimientos en cuartos y alta probabilidad de colapso.');
INSERT INTO public.rufe_formularios VALUES (26, 'fb545c4e-09b9-4a20-a16a-f0dedd5d4805', '25', 'Mulalo', 'ALTA', 'Una gata esterilizada (7 meses)', 'Vivienda Unifamiliar. Daños Estructurales en columnas. Daños Estructurales en muros y agrietamiento de piso. Peligro de colapso.');
INSERT INTO public.rufe_formularios VALUES (22, '812db15e-b798-4d9a-8683-04880e914eeb', '21', 'Paso de la torre', 'MEDIA', '2 gatos, 1 perro, 12 gallinas', 'Vivienda de un piso Bifamiliar. Tiene una tienda de Barrio Comercial. En el cuarto principal tiene una fisura en diagonal a 45 grados que atraviesa los dos cais de mampostería. Viga de gola donde funciona la tienda esta fracturada. Vivienda habitable.');
INSERT INTO public.rufe_formularios VALUES (27, '916ea82e-d3ad-4dad-b3f4-ba267cbbbccf', '26', 'Mulalo', 'ALTA', 'No tiene mascotas', 'Vivienda unifamiliar. Vive un adulto mayor con Enfermedad congenita Santiago Cuero. Muros en malas condiciones y descolapsados. Cubierta colapsada y Pisos con Asentamientos.');
INSERT INTO public.rufe_formularios VALUES (28, '4d3543a2-bc20-443d-af6b-28cc47d237b5', '27', 'Mulalo', 'ALTA', 'No tienen mascotas', 'Vivienda unifamiliar con un local comercial con un restaurant que funciona el fin de semana. Restaurante No Presenta afectaciones. Dormitorio: No se identifica un sistema de portico de Estructura. Muros con fisuras en 45 grados con Posibilidad de colapso. no Habitable y Viven en un equeque. El señor olmer Esta en etapa clinica-Dialisis y tiene amputacion de miembros inferiores y problemas de Diabetes.');
INSERT INTO public.rufe_formularios VALUES (29, '466ebb30-6d1b-4ca8-81de-88d0ceae454c', '28', 'Mulalo', 'ALTA', 'No tienen mascotas', 'Vivienda unifamiliar de un Piso. Sector de vivienda: Danos en muros con fisuras de 45 grados. Falta de vigas aereas de soporte de cubierta. Con probabilidad de colapso. No habitable. Sector local: Daños superficiales en muros - habitable.');
INSERT INTO public.rufe_formularios VALUES (30, 'fee44084-e5c2-48eb-b07c-1b3a249052e5', '29', 'Mulalo', 'ALTA', '1 gatica - No esterilizada - 8 meses', 'Vivienda un piso Unifamiliar. No Cuenta con un sistema de vigas y Columnas que permitar el Amarre de muros. Durante la actividad sisca se Presento una separacion entre muros. presentando asi un riesgo de colapso. No habitable.');
INSERT INTO public.rufe_formularios VALUES (31, '73d71e02-dfbb-4647-b83e-e00c2dd845fc', '30', 'Mulalo', 'ALTA', '1 perrito', 'Vivienda de un piso. Asentamiento de pisos. Muros con fisuras de 45. Cubierta con fisura y desplome de cubierta en el portico sea con Posibilidad de colapso. muros con fisura de 1 cm.');
INSERT INTO public.rufe_formularios VALUES (32, '962fc592-01dc-4870-a170-774e4ae82a1e', '31', 'Mulalo', 'ALTA', '2 gatos, 1 perro', 'Vivienda de un piso. Material predominante bareque y mamposteria confinada. La vivienda en bareque no es habitable y la de mamposteria confinada su cubierta es en teja de eternit y su estructura de soporte esta en muy malas condiciones. Con peligro de colapso eminente.');
INSERT INTO public.rufe_formularios VALUES (107, 'ee1ebf97-4fd7-4086-aefa-95851a87e413', '116', 'Miravalle Dapa', 'LEVE', 'No reporta', 'Averias en pañete y piso.');
INSERT INTO public.rufe_formularios VALUES (108, '1fbe25be-0cf6-47e4-87fe-7924a668a858', '117', 'Miravalle Dapa', 'LEVE', 'No reporta', 'Averia en estructura (crestería).');
INSERT INTO public.rufe_formularios VALUES (33, '2fe29f86-c6e8-4c69-9655-12a8556922a3', '32', 'Mulalo', 'ALTA', 'No reporta', 'Vivienda Unifamiliar de Dos pisos. Se evidencio un mal proceso constructivo que ocasiono fallas en muro, placas de piso y colapso de la fachada. Desplazamiento tanto interno y externo - pisos. Se recomienda a la propietaria no habitar la vivienda por un gran riesgo de colapso de la estructura.');
INSERT INTO public.rufe_formularios VALUES (34, '797a54ff-60c5-4bc4-8d07-0eebfc1d9867', '33', 'Mulalo', 'ALTA', 'No reporta', 'Vivienda mitad bareque, mitad madera. La vivienda se vio afectada parcialmente, la zona de bareque (habitaciones y sala), esta zona presentaba alto riesgo, por lo que los propietarios realizaron la demolicion para evitar accidentes y afectaciones en el resto de la vivienda. los residentes estan viviendo temporalmente en una casa de un familiar.');
INSERT INTO public.rufe_formularios VALUES (35, '7969f332-0eda-4c0c-a191-a29118c4d6f9', '34', 'Mulalo', 'BAJA', 'No reporta', 'Vivienda auxiliar colapso, estado no habitable. En esta vivienda no hay habitantes permanentemente.');
INSERT INTO public.rufe_formularios VALUES (36, '37703520-f590-4812-87ba-a73fe34520bb', '35', 'Dapa', 'ALTA', 'No reporta', 'Vivienda en alto riesgo de colapso. construccion en madera y tierra, techo eternit y zinc.');
INSERT INTO public.rufe_formularios VALUES (37, '8b401247-6d60-48a5-aa7e-25ede5226002', '36', 'Cabecera', 'ALTA', 'No reporta', 'Casa de bareque, estado actual no habitable. Riesgo de colapsar, muros y techos caidos.');
INSERT INTO public.rufe_formularios VALUES (38, '45e26e38-fde6-45b7-920d-9b75f37d23f9', '37', 'Cabecera', 'ALTA', 'No reporta', 'Vivienda en material colapsada en un 90%, se recomienda demoler totalmente. No habitable, y no tienen lugar a donde acudir.');
INSERT INTO public.rufe_formularios VALUES (39, '6061afe3-1c16-43e2-ac4d-517fca99fc34', '38', 'Dapa', 'ALTA', '15 Gallinas, 3 perros', 'Vivienda en bahareque, totalmente colapsada, perdida total. No habitable.');
INSERT INTO public.rufe_formularios VALUES (40, '0e11009e-c143-4192-9f7b-f53d91e204dc', '39', 'Salazar', 'MEDIA', 'No reporta', 'Vivienda construida en madera y mamposteria. En juntas de paredes y ventanales con grietas. Baños destruidos parcialmente. Se puede habitar la vivienda en gran parte por su tamaño y distribucion.');
INSERT INTO public.rufe_formularios VALUES (41, 'ff1e0908-6d79-44ef-b735-166fc73c56a9', '40', 'Cabecera', 'MEDIA', 'No reporta', 'Vivienda construida en baha reque completamente destruidos. Asentamiento diferencial y paredes en la mitad. Vivienda parcialmente habitable, se necesita restaurar paredes y reforzar cimientos.');
INSERT INTO public.rufe_formularios VALUES (42, 'db70c32d-a0ca-49e0-a9a8-afdb72084cc0', '41', 'Salazar', 'MEDIA', '2 Gatos, 2 Perros, 18 Gallinas', 'Vivienda construida en madera en perfecto estado y apartamento en mamposteria con derrumbe en la segunda planta en un 70%. Se recomienda demolicion de la segunda planta y construccion nuevamente. Cimientos visualmente en buen estado sin daños o fallas aparentes. Vivienda habitable en la casa de madera. Sin riesgo latente.');
INSERT INTO public.rufe_formularios VALUES (43, '0627b52c-9449-4be6-b45c-88e9baced0df', '42', 'El chocho', 'ALTA', 'No reporta', 'Vivienda construida en bahareque y mamposteria, derrumbada en un total del 80%, fallada en su estructura sin posibilidad de habitar. Terreno inestable y en riesgo latente. Evacuacion inmediata.');
INSERT INTO public.rufe_formularios VALUES (44, 'fc20bf5f-ef35-47e0-8402-70babd9562fb', '43', 'El chocho', 'BAJA', '2 Perros', 'Vivienda prefabricada habitable, con daños solamente en parte de la mamposteria de menor magnitud. Sin riesgo latente.');
INSERT INTO public.rufe_formularios VALUES (45, '478134f0-8d90-4c28-a704-bdcf459d3287', '44', 'El chocho', 'ALTA', '3 Perros, 2 Gatos', 'Vivienda construida en material, con cimentacion visiblemente fracturada. Con riesgo inminente de colapso, con asentamiento diferencial sobre la vivienda. No habitable, evacuacion inmediata.');
INSERT INTO public.rufe_formularios VALUES (46, '602a763d-d3c0-4a4a-9c3a-7f34a2b90225', '45', 'El chocho', 'MEDIA', 'No reporta', 'Vivienda presenta fallas en mamposteria, derrumbes en un 10% en parte de la segunda planta, se puede realizar una restauracion, no presenta elementos estructurales con fallas visibles. Vivienda habitable en demas distribuciones de la casa.');
INSERT INTO public.rufe_formularios VALUES (47, '06e7faad-5a0c-4dc9-ab1b-63b9baf48d1c', '46', 'El chocho', 'MEDIA', '3 perros y un gato', 'Vivienda compuesta por 3 habitaciones en bahareque de 40 años de construida y lo demas de material en bloque, daños evidenciados en la construccion de bahareque dejando (1) habitacion destruida completamente. la vivienda es habitable puesto que el resto de habitaciones y demas distribuciones se encuentran en buen estado y sin riesgo latente. Persona adulta con discapacidad perdida de vision y auditiva.');
INSERT INTO public.rufe_formularios VALUES (48, '0029babe-30af-4819-8e90-62746360f493', '47', 'Salazar', 'BAJA', '4 Perros, 15 Gallinas.', 'Vivienda Construida completamente en bahareque, con pequeños desprendimientos en Paredes de la parte de atras, se recomuenda restauracion de muros. Vivienda habitable parcialmente, sin riesgo latente.');
INSERT INTO public.rufe_formularios VALUES (49, '60d0db82-69b2-4870-a7a2-74ca8fd032ed', '48', 'Rural', 'ALTA', '2 Perros, 2 Gatos, 70 Gallinas', 'Vivienda construida en madera y bloques, derrumbada en un 80% con fallas visibles en su cimentacion. Vivienda no habitable, se recomienda demolicion total y construccion de cimientos nuevamente para proceder a construir.');
INSERT INTO public.rufe_formularios VALUES (50, '7929aaf2-8b73-4cb4-9662-04945c6538ab', '49', 'Salazar', 'ALTA', '8 perros', 'Vivienda construida en madera y bloques, presenta asentamientos diferencial en todo el terreno de apoyo, baño completamente destruido, cubierta en concreto de cuartos parcialmente derrumbada y paredes deterioradas. Vivienda no habitable, necesita reforzar cimientos y restauracion en gran parte.');
INSERT INTO public.rufe_formularios VALUES (51, 'e0fed7f9-9889-4696-9ef5-888f6afc8a72', '50', 'Salazar', 'ALTA', '1 Gallo Fino', 'Casa construida en bloques hace 15 años aproximadamente, presenta derrumbe en su mamposteria en un 70% y cubierta parcialmente derrumbada, tambien tiene deficiencias en su cimentacion. la vivienda no esta en condicion de habitabilidad.');
INSERT INTO public.rufe_formularios VALUES (52, '0a240f06-ed05-4c4f-b56e-9c8a3c058cd4', '51', 'Yumbillo', 'BAJA', '15 Gallinas, 15 Cuyes', 'Casa de bahareque de mas de 20 años construida y baño en bloques, presenta daños menores, mamposteria del baño caida y desprendimientos pequeños en partes de bahareque. La vivienda esta completamente habitable y sin riesgo latente.');
INSERT INTO public.rufe_formularios VALUES (53, 'b2a2c55f-654d-4253-91ed-82627275dceb', '52', 'Puerto Isaacs', 'ALTA', 'No reporta', 'Daños estructurales y se recomienda evacuar vivienda.');
INSERT INTO public.rufe_formularios VALUES (54, '6d1ef6db-3fc0-46cd-844f-143c9f86db3a', '53', 'Cabecera', 'MEDIA', 'No reporta', 'Recomienda demolicion de pared en cocina a traves de la debido a posible derrumbe.');
INSERT INTO public.rufe_formularios VALUES (55, '91e666fb-7822-42f0-8d10-dec0bb4bbb8b', '54', 'Cabecera', 'MEDIA', 'No reporta', 'Daño estructural debido a un incendio que tuvo anteriormente y grietas en muros.');
INSERT INTO public.rufe_formularios VALUES (56, 'd53c827a-188c-4789-b781-1c989cc7ff6f', '55', 'Cabecera', 'BAJA', 'No reporta', 'Casa habitable, se recomienda arreglar daños en muros de mamposteria.');
INSERT INTO public.rufe_formularios VALUES (57, 'f0ce707a-1104-4814-aecb-0bea5a244533', '56', 'Cabecera', 'MEDIA', 'No reporta', 'La casa se encuentra desocupada hace 1 año y 20 dias. Afectacion en infraestructura. No habitable.');
INSERT INTO public.rufe_formularios VALUES (58, '61b9335d-5b7b-49b1-a704-6dbd4ff8727f', '57', 'Cabecera', 'BAJA', 'No reporta', 'Vivienda habitable. Presenta afectacion en infraestructura.');
INSERT INTO public.rufe_formularios VALUES (59, '9ddf22a4-c416-4e1e-89e3-e748af01b065', '58', 'Cabecera', 'MEDIA', 'No reporta', 'Viga en triangulo, daño estructural parte de atras. No es habitable en la parte de atras. Ojo! Daños en la parte estructural.');
INSERT INTO public.rufe_formularios VALUES (60, 'acdb663f-c2a8-41a5-9f2d-e950941cd689', '59', 'Cabecera', 'BAJA', 'No reporta', 'La estructura se encuentra en buenas condiciones. Habitable.');
INSERT INTO public.rufe_formularios VALUES (61, '07a8e752-d77b-498c-8d4e-6ab11f2cce1c', '60', 'Cabecera', 'BAJA', 'No reporta', 'Habitable el 3er piso.');
INSERT INTO public.rufe_formularios VALUES (62, '90b5af99-31a6-436d-8034-9b3420cea2f2', '61', 'Cabecera', 'ALTA', 'No reporta', 'Vivienda en estado NO HABITABLE. Sin observaciones adicionales detalladas.');
INSERT INTO public.rufe_formularios VALUES (63, 'c4311612-4f9b-46ae-9898-8c7f8579870b', '62', 'Cabecera', 'BAJA', 'No reporta', 'Vivienda en estado HABITABLE. Sin observaciones adicionales detalladas.');
INSERT INTO public.rufe_formularios VALUES (109, 'dbd14354-d0e8-4d8b-8772-142151630648', '118', 'Miravalle Dapa', 'LEVE', 'No reporta', 'Averia en paredes.');
INSERT INTO public.rufe_formularios VALUES (110, 'dcb9a855-ca08-4cc4-b7fe-4237484e0060', '119', 'Miravalle Dapa', 'LEVE', 'No reporta', 'Averias en paredes.');
INSERT INTO public.rufe_formularios VALUES (111, '5050fefb-6ad0-4463-b73b-01ffe632097e', '120', 'Miravalle Dapa', 'LEVE', 'No reporta', 'Averias en paredes, puerta, piso.');
INSERT INTO public.rufe_formularios VALUES (112, 'dfd064ba-ac1a-483a-8278-8464b169658f', '121', 'Alto Dapa', 'LEVE', 'No reporta', 'Averias en paredes y columnas.');
INSERT INTO public.rufe_formularios VALUES (66, '2cbe4165-cd54-4668-9f23-ffdd0b6b5313', '65', 'Cabecera', 'BAJA', 'No reporta', 'Solo grietas en pintura y estuco. estructura estable, limpiar estuco y repello. Puede retornar a la normalidad.');
INSERT INTO public.rufe_formularios VALUES (67, 'a1d93bbe-7be1-4812-b9de-4801a4914396', '66', 'Cabecera', 'BAJA', 'No reporta', 'Realizar un raspado, escatificacion para evaluar las grietas. Habitable.');
INSERT INTO public.rufe_formularios VALUES (68, 'd00137c6-2d29-4444-a7e1-758bccaeaca4', '67', 'Cabecera', 'ALTA', 'No reporta', 'Desnivel casa -10°. Riesgo de colapso. No habitable.');
INSERT INTO public.rufe_formularios VALUES (69, '8e098402-855d-4aa3-a0b0-a91406a1eea0', '68', 'Cabecera', 'MEDIA', 'No reporta', 'No se observa daño estructural o muro divisorio con riesgo de caida hacia afuera la calle. Muros donde se ve grieta, se puede poner llave. Monitoreo a bordes de puertas y ventana puede haber ladrillo suelto. Sec. Gestion del Riesgo de Desastres. Sec. Infraestructura y Serv. Publicos. Arquitecto: Ovideo Seoane. Casi habitable!');
INSERT INTO public.rufe_formularios VALUES (70, '0bc1d1fa-2d8a-4449-a4f7-f469f3a1c236', '69', 'Cabecera', 'MEDIA', 'No reporta', 'Demoler 2 muros, internos y reforzar otros 2 muros. NO habitar el 3er piso.');
INSERT INTO public.rufe_formularios VALUES (71, '82f9552e-a68f-4a45-83ae-92d73bae8706', '70', 'Santa Ines', 'BAJA', '1 Gata', 'Vivienda construida en material, con grietas en muros divisorios de mamposteria y cubierta desajustada. Vivienda habitable, sin riesgo latente.');
INSERT INTO public.rufe_formularios VALUES (72, '5a374dac-9cd3-49ca-aa21-bbd587cf31ab', '71', 'El Chocho', 'BAJA', '1 Perro, 4 gallinas', 'Vivienda prefabricada con fisuras en las juntas de los modulos ceramicos del baño caidas, sin daños en elementos estructurales completamente habitable, sin riesgo latente.');
INSERT INTO public.rufe_formularios VALUES (73, '71e21b58-3fd3-4c95-bbf9-ee2eb4c69890', '72', 'Santa Ines', 'BAJA', '2 perros', 'Vivienda de bahareque con muros colapsados, necesita restauracion parcial, sin embargo hay una vivienda auxiliar de material con bloques en la cual se pueden hospedar. Vivienda habitable, sin riesgo latente.');
INSERT INTO public.rufe_formularios VALUES (74, '7b44904e-0515-4f2b-81aa-86768ff1a7eb', '73', 'Santa Ines', 'ALTA', '2 Perros', 'Vivienda en material, con estructura general deficiente, vigas y columnas mal construidas y muros fracturados y comprometidos divisores. No se recomienda habitar por gravedad de la estructura.');
INSERT INTO public.rufe_formularios VALUES (75, 'c03c943b-0ff4-428b-a0af-4e9fe0905930', '74', 'Santa Ines', 'BAJA', '2 perros', 'Vivienda en material, con fisuras en los muros divisorios de mamposteria, se recomienda reforzar su estructura. Se solicita visita de secretaria de ambiente para evaluar unos arboles que representan riesgo. Vivienda habitable sin riesgo latente.');
INSERT INTO public.rufe_formularios VALUES (76, '0528243f-5172-4dc2-b7cc-7d04817b5e6c', '75', 'Santa Ines', 'ALTA', 'No reporta', 'Vivienda colapsada por completo, inhabitable. Demoler por completo y retirar escombros.');
INSERT INTO public.rufe_formularios VALUES (77, '03816521-0a30-4f5d-945a-edde50c2daa7', '76', 'Santa Ines', 'BAJA', '2 Gatos, 1 Perro', 'Lote en construccion con muros caidos y cimentacion deficiente. Sin habitar. Sin problemas y sin riesgo.');
INSERT INTO public.rufe_formularios VALUES (78, 'a70a279e-d1b7-4643-b962-be4dec147ca1', '77', 'Santa Ines', 'ALTA', '2 Perros, 1 Gato', 'Vivienda construida en material de tres plantas con sus elementos estructurales destruidos fracturados, cubierta colapsada, muros agrietados de gran magnitud. Vivienda no habitable, con mucho riesgo. Se recomienda una evaluacion por parte de un especialista para dictaminar posible demolicion.');
INSERT INTO public.rufe_formularios VALUES (79, '8d2b3b0d-71c6-4556-afe7-f47057cd89ac', '80', 'Santa Ines', 'ALTA', '2 Perros', 'Vivienda compuesta de 2 edificaciones. 1. Una de bahareque que no presenta fallas, sin embargo, al parecer su cimentacion no parece solida, hay que inspeccion a profundidad. Y otra edificacion en material que quedo destruida, con elementos estructurales visiblemente fallados. (No habitar este predio). Vivienda no habitable, hasta hacer estudios a profundidad.');
INSERT INTO public.rufe_formularios VALUES (80, '07e6ba4e-9b57-4328-8762-aa25edb82aed', '81', 'Santa Ines', 'BAJA', '1 Perro, 1 gato', 'Vivienda construida en prefabricado. Con fisuras entre modulos y revoque caido. No hay riesgo latente. Vivienda habitable.');
INSERT INTO public.rufe_formularios VALUES (81, 'bcc1fb33-d3bc-4123-b46b-18b4a7d98164', '82', 'Santa Ines', 'ALTA', '2 Perros', 'Vivienda con muros colapsados de mamposteria con el acero de los elementos estructurales visibles pero sin fallas. Vivienda parcialmente colapsada, inhabitable. Demoler por completo y retirar escombros.');
INSERT INTO public.rufe_formularios VALUES (83, 'ded1140d-cf57-457b-8845-d8297a354ae2', '64', 'Cabecera', 'MEDIA', 'No reporta', 'Requerir a la seguradora revision y reparacion de elementos facturados de los 5 pisos, con repello, estuco y pintura. contactar a movilidad para apoyo en revisiones externas desmontar vidrios fracturados, y cambio fachaletas de edificio y despues de eso pueden retornar a la normalidad. Revisar escalera. Presenta la misma grieta en todos los Pisos.');
INSERT INTO public.rufe_formularios VALUES (84, 'b5d778aa-78a2-4e1e-ad39-78e20b673313', '78', 'Santa Ines', 'BAJA', '1 Gato, 1 Perro', 'Vivienda con fisuras en los muros de mamposteria y un elemento estructural aparentemente con falla, sin embargo no existe fractura en el acero y es muy minimo. Vivienda habitable, sin riesgo.');
INSERT INTO public.rufe_formularios VALUES (85, '6caeec38-8399-416c-9995-ffd6f9f2cd73', '79', 'Santa Ines', 'BAJA', 'No reporta', 'Vivienda en material con fisuras y grietas en muros divisorios, completamente habitable. Sin riesgo latente.');
INSERT INTO public.rufe_formularios VALUES (86, '73fa5c90-051b-4661-b4a9-ff2fe5adbb33', '95', 'Alto Dapa', 'ALTA', 'No reporta', 'Casa destruida en un 85%. Madre cabeza de hogar. Prioridad alta');
INSERT INTO public.rufe_formularios VALUES (87, 'b9e0558f-e327-4ed1-a243-5cf4e6ab5650', '96', 'Alto Dapa', 'ALTA', 'No reporta', 'Averias en paredes, columnas, vigas. Se requiere reubicacion. Prioridad alta');
INSERT INTO public.rufe_formularios VALUES (88, 'a9ff851d-0b27-4f47-9cc8-a9c24f5f10fd', '97', 'Alto Dapa', 'ALTA', 'No reporta', 'Casa en perdida total. Los propietarios requieren reubicacion urgente. Prioridad alta');
INSERT INTO public.rufe_formularios VALUES (89, '118a3c3e-f74e-4f86-9463-034a496fdfba', '98', 'Yumbillo', 'ALTA', 'No reporta', 'Casa en perdida total. Se requiere reubicacion. Prioridad alta');
INSERT INTO public.rufe_formularios VALUES (90, 'e3e6c2d9-d1e2-42ad-b64a-b141496784be', '99', 'Yumbillo', 'ALTA', 'No reporta', 'Vivienda apta en su totalidad. Prioridad alta');
INSERT INTO public.rufe_formularios VALUES (91, '26a01f01-a632-4d41-88fb-88997d98ae53', '100', 'Alto Dapa', 'ALTA', 'No reporta', 'Edificaciom con grietas severas en columnas, vigas, paredes y pisos. Se recomienda reubicacion y apoyo urgente. Prioridad alta');
INSERT INTO public.rufe_formularios VALUES (92, '4a260f54-7a7d-4ec5-b4db-69f7a82d077a', '101', 'Alto Dapa', 'ALTA', 'No reporta', 'Casa de tres pisos con agrietamiento en el segundo piso de columnas, vigas, paredes. Prioridad alta');
INSERT INTO public.rufe_formularios VALUES (93, '13b59e3f-158c-4037-b233-b44b08ba6f21', '102', 'Yumbo', 'ALTA', 'No reporta', 'Paredes en bahareque sin columnas, fracturadas e inestables a punto de colapsar. Adulta mayor con discapacidad en cama. Prioridad alta');
INSERT INTO public.rufe_formularios VALUES (94, '694f86ea-51cf-4ce4-b7d2-62a75947ac92', '103', 'Alto Dapa', 'ALTA', 'No reporta', 'Averias en paredes, columnas. Madre en embarazo, se requiere reubicacion. Prioridad alta');
INSERT INTO public.rufe_formularios VALUES (95, 'b26a0c3d-10ab-44da-af7d-bd6356b8b201', '104', 'Alto Dapa', 'MEDIA', 'No reporta', 'Averias en paredes y pisos. Prioridad media');
INSERT INTO public.rufe_formularios VALUES (96, '77f0e879-4a0d-41be-9b0b-182b773f4315', '105', 'Alto Dapa', 'MEDIA', 'No reporta', 'Averias en paredes, columnas y vigas. Adulto mayor. Prioridad media');
INSERT INTO public.rufe_formularios VALUES (97, '71fd274c-207d-4080-a546-34f164972762', '106', 'Alto Dapa', 'MEDIA', 'No reporta', 'Sistema Estructural Agrietado con riesgo de Colapso. mamposteria comprometida. 3 inquilinos mas.');
INSERT INTO public.rufe_formularios VALUES (98, '66944a33-e7f3-4c8d-87d1-2f9180389618', '107', 'Alto Dapa', 'MEDIA', 'No reporta', 'Averia en Paredes y Baño');
INSERT INTO public.rufe_formularios VALUES (99, 'fd963454-8785-456d-86ce-f1c6145cb214', '109', 'Alto Dapa', 'MEDIA', 'No reporta', 'Averias en paredes, pisos y columnas');
INSERT INTO public.rufe_formularios VALUES (100, 'a0d5723b-7228-4568-9ed5-bfe6c75ae031', '110', 'Yumbillo', 'MEDIA', 'No reporta', 'Casa prefabricada con afectacion en planchas y techo');
INSERT INTO public.rufe_formularios VALUES (101, '29a0be2a-55e0-4f5d-8173-18071028135d', '108', 'Alto Dapa', 'MEDIA', 'No reporta', 'Vivienda de dos pisos con segundo piso prefabricado con bloqueta y empalmes.');
INSERT INTO public.rufe_formularios VALUES (102, '4c88080f-a16a-4e5a-a84c-3145428bc4a9', '111', 'Miravalle Dapa', 'LEVE', 'No reporta', 'Averias en paredes.');
INSERT INTO public.rufe_formularios VALUES (103, 'b38b2b87-5dbe-4c0e-a6ae-5a2615629461', '112', 'Miravalle Dapa', 'LEVE', 'No reporta', 'Averia en paredes.');
INSERT INTO public.rufe_formularios VALUES (104, 'a536c8c8-c6f3-471d-9397-0a0c6913a844', '113', 'Miravalle Dapa', 'LEVE', 'No reporta', 'Averia en paredes.');
INSERT INTO public.rufe_formularios VALUES (105, '0373fc52-c8a3-4577-9ad0-fa3e7f369135', '114', 'Miravalle Dapa', 'LEVE', 'No reporta', 'Averias en paredes.');
INSERT INTO public.rufe_formularios VALUES (106, 'c3209f27-c9d6-4881-8916-15336222ca71', '115', 'Miravalle Dapa', 'LEVE', 'No reporta', 'Averias en paredes.');
INSERT INTO public.rufe_formularios VALUES (113, 'df5933a7-1df5-4907-8af8-a370fdac09d5', '122', 'Alto Dapa', 'LEVE', 'No reporta', 'Vivienda en construcción - mampostería. Paredes afectadas.');
INSERT INTO public.rufe_formularios VALUES (114, '960668b0-2a27-422b-90da-cd0ee734992e', '123', 'Alto Dapa', 'LEVE', 'No reporta', 'Averias en paredes.');
INSERT INTO public.rufe_formularios VALUES (115, 'a64a57d3-c80d-45a7-b35b-9dc2043f8904', '124', 'Alto Dapa', 'LEVE', 'No reporta', 'Averias en paredes y pañete.');
INSERT INTO public.rufe_formularios VALUES (116, '9cb0a45c-cf84-4442-a138-7a69f973e51f', '125', 'Alto Dapa', 'LEVE', 'No reporta', 'Averias en pañete y piso.');
INSERT INTO public.rufe_formularios VALUES (117, 'ba2a552c-dca8-4f0f-b3ee-a04b58b297c2', '127', 'Manga Dapa', 'MEDIA', '2 Gatos', 'Vivienda construida mitad de bahareque y mitad de material, afectaciones en el muro perimetral de la parte de bahareque, se encuentra desprendido. Habitan 2 adultos mayores, uno de ellos con discapacidad.');
INSERT INTO public.rufe_formularios VALUES (118, '00418439-4824-469d-b777-a74080b4ac70', '128', 'Manga Dapa', 'BAJA', '2 Perros, 3 Gatos', 'Vivienda presenta grietas en muros de mampostería y una viga de amarré que perdió revestimiento. Tratar con inmediatez el elemento estructural comprometido. La cosa es habitable, no tiene fallos de gravedad.');
INSERT INTO public.rufe_formularios VALUES (119, '49afe21f-b870-4ade-a0ba-6c9bd7615c8a', '129', 'Manga Dapa', 'BAJA', '1 Gato', 'Vivienda construida en bahareque, con fisuras en los juntas de los muros; y pocos desprendimientos en zonas. Se encuentra habitable la vivienda, sin riesgo latente.');
INSERT INTO public.rufe_formularios VALUES (120, '7c980e93-6aec-4a68-a7fa-bd207f0b3341', '130', 'Manga Dapa', 'MEDIA', '4 Gatos', 'Vivienda construida en madera, sin afectaciones en su estructura, pero con un talud de tierra reposado en la parte de atrás de la vivienda, con riesgo latente de movimiento en masa.');
INSERT INTO public.rufe_formularios VALUES (121, '65112b94-e041-4dc5-99dd-a6f6b2c70258', '131', 'Manga Dapa', 'BAJA', '1 Perro, 4 Gatos, 1 Loro', 'Vivienda con fisuras en baldosas del piso y fisuras en los muros de mampostería en las juntas con columnas y caída de balcón en segundo planta. Es habitable, su propietario hizo las adecuaciones pertinentes y no existe riesgo latente.');
INSERT INTO public.rufe_formularios VALUES (122, '1c71f46b-29eb-4443-920f-245b5e387887', '132', 'Manga Dapa', 'ALTA', '3 Gatos, 1 Perro, 20 Gallinas', 'Vivienda consumida en su totalidad por incendio, pérdida total.');
INSERT INTO public.rufe_formularios VALUES (123, '42def1b1-15ab-4ca2-99c2-f9cb1a3e730f', '133', 'Manga Dapa', 'BAJA', '4 Perros, 2 Gatos, 1 Chivo', 'Vivienda construida en bahareque, con fisuras en las juntas de los muros y desprendimiento de material de los mismos. Completamente habitable, sin riesgo latente.');
INSERT INTO public.rufe_formularios VALUES (124, '068fbf36-cac7-404d-9f77-6a285f2d1a3c', '134', 'Manga Dapa', 'MEDIA', '3 Gatos, 2 Perros, 4 Gallinas, 2 Codornices', 'Vivienda construida en material, con múltiples grietas y fisuras en muros, con cubierta parcialmente colapsada, con elementos estructurales sin fallos visuales. Se recomienda evacuar la vivienda hasta que se realicen los arreglos pertinentes.');
INSERT INTO public.rufe_formularios VALUES (125, '273b8873-6a63-4fc5-b3ae-97e7d92cefe1', '135', 'Manga Dapa', 'BAJA', '1 Gato, 3 Perros', 'Vivienda con fisuras en juntas de muro de mampostería con columnas y desprendimiento de recubrimiento en vigas. Se encuentra habitable, el propietario ya hizo restauración y no existe riesgo.');
INSERT INTO public.rufe_formularios VALUES (126, 'd9cbb5c8-259a-41a6-8841-f70711b4090a', '136', 'Manga Dapa', 'BAJA', 'No reporta', 'Vivienda con afectaciones leves, fisuras en mampostería de muros divisorios de poca envergadura, sin riesgo latente. Completamente habitable.');
INSERT INTO public.rufe_formularios VALUES (127, 'c5688147-1c23-4651-8058-720ea3ebd925', '137', 'Manga Dapa', 'ALTA', '2 Perros', 'Vivienda construida en material con muros fracturados en su totalidad con columnas construidos en solo ladrillos, sin acero estructural ni concreto, también follados, con riesgo latente de colapso. También tiene la cubierta parcialmente colapsada. No habitable.');
INSERT INTO public.rufe_formularios VALUES (128, '4b87a9cc-bbb3-43ee-9fdb-3316b1a0aedc', '138', 'Manga Dapa', 'BAJA', '3 Perros, 2 Gatos, 20 Gallinas', 'Vivienda de dos plantas, con fisuras y grietas en muros divisorios, leves separaciones en juntas entre columnas y muros, y cubierta desplazada. Recomiendo demoler muros fracturados, riesgo latente. Es habitable tomando las medidas de precaución.');
INSERT INTO public.rufe_formularios VALUES (129, '4797d482-f1e6-4084-b743-cc07a4722421', '139', 'Manga Dapa', 'ALTA', '1 Perro', 'Vivienda en material con sus muros internos sueltos, presentan riesgo de colapso grave. Vivienda no habitable a pesar de que sus vigas y columnas no presentan fallas, su mampostería está comprometida, vive un niño con discapacidad.');
INSERT INTO public.rufe_formularios VALUES (130, 'd29aa432-f397-4173-b7e4-a3d18f6d60e4', '140', 'Manga Dapa', 'ALTA', '2 Perros, 4 Gatos', 'Vivienda de bahareque con sus muros colapsados y soportes debilitados, con riesgo latente. Se recomienda no habitar, los propietarios no tienen donde albergarse.');
INSERT INTO public.rufe_formularios VALUES (131, '52fdc060-3952-4437-ad34-f3614b0f68b2', '141', 'Manga Vieja', 'MEDIA', '10 Pollos, 1 Gato', 'Vivienda construida en material, con desplomes en muros divisorios, y fisuras en sus juntas y cuchilla, elementos estructurales ausentes en partes de la vivienda.');
INSERT INTO public.rufe_formularios VALUES (132, '89ad8c08-0f35-40f7-8a87-719037f7834b', '142', 'Panorama', 'ALTA', 'No reporta', '2 adultos mayores con discapacidad visual.');
INSERT INTO public.rufe_formularios VALUES (133, 'e73abe7e-4a74-4e2c-8af1-29bc30d86ef5', '143', 'Las Américas', 'MEDIA', 'No reporta', 'Se observan daños en mampostería no estructural, se recomienda demoler muro frontal 2do piso, revisar ladrillos, puede ser sub-repello.');
INSERT INTO public.rufe_formularios VALUES (134, '362088e4-aaa4-4abb-9bfa-3d0540dfa46b', '144', 'Panorama', 'BAJA', 'No reporta', 'Evaluación sin daños estructurales mayores registrados.');
INSERT INTO public.rufe_formularios VALUES (135, '2cc4baa8-6562-4c95-9069-ed16acc9f95e', '145', 'Belalcazar', 'BAJA', 'No reporta', 'Vivienda habitable segura.');
INSERT INTO public.rufe_formularios VALUES (136, '29366f11-ff12-4f38-84be-faa58fb44572', '146', 'Panorama', 'BAJA', 'No reporta', 'Se evidencia daño en paredes no estructurales, supervisor que no sean fracturas, o revoque.');
INSERT INTO public.rufe_formularios VALUES (137, '561c73df-3a07-4302-99ab-db9d21aa2bd5', '147', 'Panorama', 'BAJA', 'No reporta', 'Se requiere reparación dintel del baño. Atención social / Ojo: Necesita silla de ruedas.');
INSERT INTO public.rufe_formularios VALUES (138, '77eeca52-8220-434c-850c-71ac67744e0d', '126', 'Alto Dapa', 'LEVE', 'No reporta', 'Averias en pañete y muros.');
